{
  "name": "ember-and-oak",
  "version": "0.1.0",
  "private": true,
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start",
    "lint": "eslint"
  },
  "dependencies": {
    "framer-motion": "^13.2.0",
    "lucide-react": "^1.45.0",
    "next": "16.3.5",
    "react": "19.2.8",
    "react-dom": "19.2.8"
  },
  "devDependencies": {
    "@tailwindcss/postcss": "^4",
    "@types/node": "^20",
    "@types/react": "^19",
    "@types/react-dom": "^19",
    "eslint": "^9",
    "eslint-config-next": "16.3.5",
    "tailwindcss": "^4",
    "typescript": "^5"
  },
  "type": "module"
}
"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";
import { Menu, X } from "lucide-react";
import site from "@/content/site";

/**
 * Sticky navigation: Fraunces italic wordmark left, uppercase links right,
 * 1px hairline underneath. Below `md` it collapses to a hamburger that opens
 * a full-screen overlay using the same typographic language.
 */
export default function Navbar() {
  const pathname = usePathname();
  const [open, setOpen] = useState(false);
  const [renderedFor, setRenderedFor] = useState(pathname);

  // Close the overlay on navigation. Done during render (not in an effect) so
  // the menu never paints open on the new route.
  if (renderedFor !== pathname) {
    setRenderedFor(pathname);
    if (open) setOpen(false);
  }

  // Lock body scroll and support Escape while the overlay is open.
  useEffect(() => {
    if (!open) return;

    const { overflow } = document.body.style;
    document.body.style.overflow = "hidden";

    function onKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") setOpen(false);
    }

    window.addEventListener("keydown", onKeyDown);
    return () => {
      document.body.style.overflow = overflow;
      window.removeEventListener("keydown", onKeyDown);
    };
  }, [open]);

  function isActive(href: string) {
    return href === "/" ? pathname === "/" : pathname.startsWith(href);
  }

  return (
    <header className="sticky top-0 z-30 border-b bg-bg/95 backdrop-blur-[2px]">
      <nav
        aria-label="Primary"
        className="mx-auto flex max-w-shell items-center justify-between px-5 py-4 sm:px-8 md:py-5"
      >
        <Link
          href="/"
          className="font-display text-[22px] italic leading-none tracking-[-0.02em] transition-colors duration-300 hover:text-primary"
        >
          {site.business.name}
        </Link>

        {/* Desktop links */}
        <ul className="hidden items-center gap-8 md:flex">
          {site.nav.map((link) => (
            <li key={link.href}>
              <Link
                href={link.href}
                aria-current={isActive(link.href) ? "page" : undefined}
                className={`label-caps transition-colors duration-300 hover:text-primary ${
                  isActive(link.href) ? "text-primary" : "text-ink"
                }`}
              >
                {link.label}
              </Link>
            </li>
          ))}
        </ul>

        {/* Mobile trigger with 44px min touch target and accessible ARIA attributes */}
        <button
          type="button"
          onClick={() => setOpen(true)}
          aria-label="Open navigation menu"
          aria-expanded={open}
          aria-controls="mobile-menu"
          className="-mr-2 flex h-11 w-11 items-center justify-center text-ink md:hidden"
        >
          <Menu size={22} strokeWidth={1.5} aria-hidden="true" />
        </button>
      </nav>

      {/* Full-screen overlay menu */}
      {open ? (
        <div
          id="mobile-menu"
          className="fixed inset-0 z-50 flex flex-col bg-bg md:hidden"
          role="dialog"
          aria-modal="true"
          aria-label="Site menu"
        >
          <div className="flex items-center justify-between border-b px-5 py-4">
            <span className="font-display text-[22px] italic leading-none tracking-[-0.02em]">
              {site.business.name}
            </span>
            <button
              type="button"
              onClick={() => setOpen(false)}
              aria-label="Close navigation menu"
              autoFocus
              className="-mr-2 flex h-11 w-11 items-center justify-center text-ink"
            >
              <X size={22} strokeWidth={1.5} aria-hidden="true" />
            </button>
          </div>

          <ul className="flex flex-1 flex-col justify-center px-5 pb-24">
            {site.nav.map((link) => (
              <li key={link.href} className="border-b last:border-b-0">
                <Link
                  href={link.href}
                  aria-current={isActive(link.href) ? "page" : undefined}
                  className={`label-caps block py-6 ${
                    isActive(link.href) ? "text-primary" : "text-ink"
                  }`}
                >
                  {link.label}
                </Link>
              </li>
            ))}
          </ul>

          <div className="border-t px-5 py-6">
            <a
              href={site.business.phoneHref}
              className="font-display text-2xl tracking-[-0.02em]"
            >
              {site.business.phone}
            </a>
            <p className="eyebrow mt-2">{site.business.demoLabel}</p>
          </div>
        </div>
      ) : null}
    </header>
  );
}
"use client";

import { useEffect, useRef, useState } from "react";
import site from "@/content/site";

/**
 * Fixed WhatsApp action button. Pulses once the visitor has started scrolling,
 * then stays still.
 */
export default function WhatsAppFab() {
  const [pulsed, setPulsed] = useState(false);
  const fired = useRef(false);

  useEffect(() => {
    function onScroll() {
      if (fired.current || window.scrollY < 240) return;
      fired.current = true;
      setPulsed(true);
      window.setTimeout(() => setPulsed(false), 3400);
    }

    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <a
      href={site.business.whatsapp}
      target="_blank"
      rel="noopener noreferrer"
      aria-label={`Message ${site.business.name} on WhatsApp`}
      className={`fixed bottom-5 right-5 z-40 flex h-14 w-14 items-center justify-center rounded-full bg-primary text-bg transition-colors duration-300 hover:bg-ink ${
        pulsed ? "animate-fab-pulse" : ""
      }`}
    >
      <svg
        viewBox="0 0 24 24"
        width="26"
        height="26"
        fill="currentColor"
        aria-hidden="true"
      >
        <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51l-.57-.01c-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.872.118.571-.085 1.758-.719 2.006-1.413.247-.694.247-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884a9.82 9.82 0 016.988 2.896 9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.885-9.885 9.885m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893A11.821 11.821 0 0020.465 3.49" />
      </svg>
    </a>
  );
}
@import "tailwindcss";
@config "../tailwind.config.ts";

/* =========================================================
   Design tokens — the ONLY place raw colour values live.
   Components reference the Tailwind mappings (bg-bg, text-ink,
   border-hairline, ...) declared in tailwind.config.ts.
   ========================================================= */
:root {
  --color-bg: #faf7f2; /* warm cream, page background */
  --color-surface: #ffffff; /* cards / panels */
  --color-ink: #1c1917; /* primary text, near-black warm */
  --color-muted: #78716c; /* secondary text */
  --color-primary: #b45309; /* burnt amber — buttons, accents only */
  --color-hairline: #e7e5e4; /* 1px borders / dividers */

  --font-display: var(--font-fraunces), ui-serif, Georgia, serif;
  --font-body: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
}

@layer base {
  html {
    -webkit-text-size-adjust: 100%;
  }

  body {
    background-color: var(--color-bg);
    color: var(--color-ink);
    font-family: var(--font-body);
    font-size: 17px;
    line-height: 1.7;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  h1,
  h2,
  h3,
  h4 {
    font-family: var(--font-display);
    font-optical-sizing: auto;
    letter-spacing: -0.02em;
    line-height: 1.05;
    text-wrap: balance;
  }

  /* Hairlines are the primary structural device of this design. */
  hr {
    border: 0;
    border-top: 1px solid var(--color-hairline);
  }

  :focus-visible {
    outline: 2px solid var(--color-primary);
    outline-offset: 3px;
  }

  /* Inputs never below 16px — prevents iOS zoom-on-focus. */
  input,
  select,
  textarea,
  button {
    font-family: inherit;
    font-size: 16px;
  }

  ::selection {
    background: var(--color-ink);
    color: var(--color-bg);
  }
}

@layer components {
  /* Eyebrow label — Inter 12px, uppercase, 0.15em tracking, muted. */
  .eyebrow {
    font-size: 12px;
    line-height: 1.4;
    text-transform: uppercase;
    letter-spacing: 0.15em;
    color: var(--color-muted);
  }

  /* Shared uppercase micro-label used by nav links and buttons. */
  .label-caps {
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.15em;
    line-height: 1;
  }

  .display-hero {
    font-size: clamp(2.75rem, 7vw, 6rem);
  }

  .display-xl {
    font-size: clamp(2.25rem, 5.5vw, 4rem);
  }

  .display-lg {
    font-size: clamp(1.75rem, 3.6vw, 2.75rem);
  }

  /* Body copy measure. */
  .prose-measure {
    max-width: 65ch;
  }
}

/* ---------- Keyframes (the only motion defined in CSS) ---------- */

/* Hero: slow 12s zoom on load, once. */
@keyframes hero-zoom {
  from {
    transform: scale(1);
  }
  to {
    transform: scale(1.08);
  }
}

.animate-hero-zoom {
  animation: hero-zoom 12s ease-out forwards;
}

/* Marquee: slow 30s loop. */
/* Two identical halves each shift left by their own full width, so the
   loop restarts exactly where it began. */
@keyframes marquee-scroll {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-100%);
  }
}

.animate-marquee {
  animation: marquee-scroll 30s linear infinite;
}

/* WhatsApp FAB: subtle one-shot pulse when first scrolled into view. */
@keyframes fab-pulse {
  0% {
    box-shadow: 0 0 0 0 rgb(180 83 9 / 45%);
  }
  100% {
    box-shadow: 0 0 0 18px rgb(180 83 9 / 0%);
  }
}

.animate-fab-pulse {
  animation: fab-pulse 1.6s ease-out 2;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

